query Enrich($mpn: String!) {
  supMultiMatch(queries: [{ mpn: $mpn, limit: 1 }], currency: "USD", country: "US") {
    hits
    parts {
      id
      mpn
      name
      octopartUrl
      manufacturer { name }
      medianPrice1000 { price currency quantity }
      totalAvail
      sellers {
        isAuthorized
        company { name }
        offers {
          inventoryLevel
          factoryLeadDays
          prices { quantity price currency }
        }
      }
    }
  }
}
